apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/assets/app.css
+:root{
+  --bg: #f6f7fb;
+  --surface: #ffffff;
+  --surface-2: #f9fafb;
+  --border: rgba(13,20,33,.10);
+  --text: #0D1421;
+  --muted: #808A9D;
+  --blue: #3861FB;
+  --green: #16c784;
+  --red: #ea3943;
+  --shadow: 0 1px 0 rgba(0,0,0,.03), 0 10px 30px rgba(13,20,33,.06);
+  --shadow-sm: 0 1px 0 rgba(0,0,0,.03), 0 6px 18px rgba(13,20,33,.06);
+  --ring: 0 0 0 3px rgba(56,97,251,.18);
+  --radius: 14px;
+  --radius-sm: 10px;
+  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
+  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
+}
+
+*{box-sizing:border-box}
+html,body{height:100%}
+body{
+  margin:0;
+  font-family: var(--sans);
+  color: var(--text);
+  background: radial-gradient(1200px 420px at 30% -10%, rgba(56,97,251,.10), transparent 60%),
+              radial-gradient(900px 360px at 90% 0%, rgba(22,199,132,.08), transparent 55%),
+              var(--bg);
+}
+a{color:inherit; text-decoration:none}
+button{font-family:inherit}
+
+.container{
+  max-width: 1440px;
+  margin: 0 auto;
+  padding: 18px 18px 36px;
+}
+
+.topnav{
+  position: sticky;
+  top: 0;
+  z-index: 40;
+  background: rgba(246,247,251,.80);
+  backdrop-filter: blur(10px);
+  border-bottom: 1px solid rgba(13,20,33,.07);
+}
+
+.topnav-inner{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:14px;
+  padding: 12px 18px;
+  max-width: 1440px;
+  margin: 0 auto;
+}
+
+.brand{
+  display:flex;
+  align-items:center;
+  gap:10px;
+  min-width: 230px;
+}
+
+.brand-badge{
+  width: 34px;
+  height: 34px;
+  border-radius: 12px;
+  background: linear-gradient(135deg, rgba(56,97,251,1), rgba(56,97,251,.65));
+  box-shadow: 0 10px 20px rgba(56,97,251,.18);
+  position: relative;
+  overflow:hidden;
+}
+.brand-badge::after{
+  content:"";
+  position:absolute;
+  inset:-12px;
+  background: radial-gradient(circle at 30% 20%, rgba(255,255,255,.55), transparent 45%);
+}
+.brand-title{
+  display:flex;
+  flex-direction:column;
+  line-height:1.1;
+}
+.brand-title strong{font-size: 13px; letter-spacing:.2px}
+.brand-title span{font-size: 11px; color: var(--muted)}
+
+.navlinks{display:flex; align-items:center; gap: 6px; flex-wrap:wrap}
+.navlinks a{
+  padding: 8px 10px;
+  border-radius: 999px;
+  color: rgba(13,20,33,.78);
+  font-size: 12px;
+  font-weight: 600;
+}
+.navlinks a[aria-current="page"], .navlinks a:hover{
+  background: rgba(56,97,251,.10);
+  color: var(--text);
+}
+
+.nav-actions{display:flex; align-items:center; gap: 10px}
+.btn{
+  border: 1px solid rgba(13,20,33,.10);
+  background: rgba(255,255,255,.72);
+  color: var(--text);
+  border-radius: 999px;
+  padding: 9px 12px;
+  font-size: 12px;
+  font-weight: 650;
+  cursor:pointer;
+  box-shadow: 0 1px 0 rgba(0,0,0,.02);
+}
+.btn:hover{background: rgba(255,255,255,.95)}
+.btn:focus-visible{outline:none; box-shadow: var(--ring)}
+.btn.primary{
+  border-color: rgba(56,97,251,.30);
+  background: linear-gradient(180deg, rgba(56,97,251,1), rgba(56,97,251,.86));
+  color: white;
+}
+.btn.primary:hover{filter:saturate(1.05) brightness(1.02)}
+
+.grid{
+  display:grid;
+  gap: 14px;
+}
+
+.statsbar{
+  display:grid;
+  gap: 10px;
+  grid-template-columns: 1.3fr 1fr 1fr 1fr;
+  align-items:stretch;
+}
+
+.card{
+  background: rgba(255,255,255,.84);
+  border: 1px solid rgba(13,20,33,.08);
+  border-radius: var(--radius);
+  box-shadow: var(--shadow);
+}
+
+.stat{
+  padding: 14px 14px;
+  display:flex;
+  align-items:flex-start;
+  justify-content:space-between;
+  gap: 14px;
+}
+.stat .label{font-size: 11px; color: rgba(13,20,33,.60); font-weight: 700; letter-spacing:.2px}
+.stat .value{font-size: 16px; font-weight: 800; margin-top: 4px}
+.stat .sub{font-size: 11px; color: var(--muted); margin-top: 4px}
+.pill{
+  display:inline-flex;
+  align-items:center;
+  gap: 6px;
+  border-radius: 999px;
+  padding: 6px 10px;
+  font-size: 11px;
+  font-weight: 750;
+  border: 1px solid rgba(13,20,33,.10);
+  background: rgba(255,255,255,.85);
+  white-space:nowrap;
+}
+.pill.positive{border-color: rgba(22,199,132,.35); color: var(--green); background: rgba(22,199,132,.06)}
+.pill.negative{border-color: rgba(234,57,67,.35); color: var(--red); background: rgba(234,57,67,.06)}
+.pill.neutral{border-color: rgba(128,138,157,.35); color: rgba(13,20,33,.72); background: rgba(128,138,157,.08)}
+
+.banner{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: 14px;
+  padding: 12px 12px;
+}
+.banner .title{font-size: 12px; font-weight: 750}
+.banner .meta{font-size: 11px; color: var(--muted)}
+.banner-controls{display:flex; align-items:center; gap: 8px}
+.iconbtn{
+  width: 34px; height: 34px;
+  border-radius: 12px;
+  border: 1px solid rgba(13,20,33,.10);
+  background: rgba(255,255,255,.80);
+  cursor:pointer;
+}
+.iconbtn:hover{background: rgba(255,255,255,.98)}
+.iconbtn:focus-visible{outline:none; box-shadow: var(--ring)}
+
+.ai-bar{
+  padding: 12px 12px;
+  display:flex;
+  align-items:flex-start;
+  justify-content:space-between;
+  gap: 14px;
+}
+.ai-left{display:flex; flex-direction:column; gap: 8px}
+.ai-title{font-size: 12px; color: rgba(13,20,33,.72); font-weight: 800}
+.chips{display:flex; flex-wrap:wrap; gap: 8px}
+.chip{
+  border: 1px solid rgba(13,20,33,.10);
+  background: rgba(255,255,255,.86);
+  color: rgba(13,20,33,.82);
+  border-radius: 999px;
+  padding: 8px 10px;
+  font-size: 12px;
+  font-weight: 650;
+  cursor:pointer;
+}
+.chip:hover{border-color: rgba(56,97,251,.35); box-shadow: 0 0 0 3px rgba(56,97,251,.10)}
+
+.tabs{
+  display:flex;
+  gap: 8px;
+  flex-wrap:wrap;
+}
+.tab{
+  border: 1px solid rgba(13,20,33,.10);
+  background: rgba(255,255,255,.78);
+  color: rgba(13,20,33,.78);
+  border-radius: 999px;
+  padding: 8px 10px;
+  font-size: 12px;
+  font-weight: 700;
+  cursor:pointer;
+}
+.tab:hover{background: rgba(255,255,255,.96)}
+.tab[aria-selected="true"]{
+  border-color: rgba(56,97,251,.35);
+  background: rgba(56,97,251,.10);
+  color: var(--text);
+}
+.tab:focus-visible{outline:none; box-shadow: var(--ring)}
+
+.panel{
+  padding: 12px 12px;
+}
+
+.table-head{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: 12px;
+  padding: 14px 14px 10px;
+}
+.table-title{display:flex; align-items:baseline; gap: 10px}
+.table-title h1{margin:0; font-size: 16px; font-weight: 900}
+.table-title span{font-size: 11px; color: var(--muted); font-weight: 650}
+.controls{display:flex; align-items:center; gap: 8px; flex-wrap:wrap}
+
+.select{
+  display:inline-flex;
+  align-items:center;
+  gap: 8px;
+  border: 1px solid rgba(13,20,33,.10);
+  background: rgba(255,255,255,.78);
+  padding: 9px 10px;
+  border-radius: 999px;
+  font-size: 12px;
+  font-weight: 750;
+  cursor:pointer;
+}
+.select:focus-visible{outline:none; box-shadow: var(--ring)}
+
+.dropdown{
+  position: relative;
+}
+.menu{
+  position:absolute;
+  right:0;
+  top: calc(100% + 10px);
+  width: 260px;
+  background: rgba(255,255,255,.98);
+  border: 1px solid rgba(13,20,33,.10);
+  border-radius: 14px;
+  box-shadow: var(--shadow);
+  padding: 10px;
+  display:none;
+}
+.menu.open{display:block}
+.menu h3{margin: 4px 0 10px; font-size: 12px; font-weight: 900}
+.menu .row{display:flex; align-items:center; justify-content:space-between; gap: 10px; padding: 8px 8px; border-radius: 10px}
+.menu .row:hover{background: rgba(13,20,33,.04)}
+.menu label{font-size: 12px; font-weight: 700; color: rgba(13,20,33,.80)}
+.menu input[type="checkbox"]{width: 16px; height: 16px}
+.menu .hint{font-size: 11px; color: var(--muted); margin-top: 8px; line-height:1.35}
+
+.filters-panel{
+  display:none;
+  border-top: 1px solid rgba(13,20,33,.08);
+  padding: 12px 14px 14px;
+}
+.filters-panel.open{display:block}
+.filters-grid{display:grid; grid-template-columns: repeat(4, 1fr); gap: 12px}
+.field{display:flex; flex-direction:column; gap:6px}
+.field label{font-size: 11px; color: rgba(13,20,33,.65); font-weight: 800}
+.field input,.field select{
+  border: 1px solid rgba(13,20,33,.10);
+  background: rgba(255,255,255,.90);
+  border-radius: 12px;
+  padding: 10px 10px;
+  font-size: 12px;
+}
+.field input:focus,.field select:focus{outline:none; box-shadow: var(--ring); border-color: rgba(56,97,251,.35)}
+.field small{font-size: 11px; color: var(--muted); line-height:1.3}
+
+.table-wrap{
+  overflow:auto;
+  border-top: 1px solid rgba(13,20,33,.08);
+}
+
+table{
+  width: 100%;
+  border-collapse: separate;
+  border-spacing: 0;
+  min-width: 1180px;
+}
+
+thead th{
+  position: sticky;
+  top: 0;
+  z-index: 2;
+  background: rgba(249,250,251,.92);
+  backdrop-filter: blur(8px);
+  border-bottom: 1px solid rgba(13,20,33,.10);
+  padding: 10px 10px;
+  font-size: 11px;
+  color: rgba(13,20,33,.62);
+  text-align:left;
+  letter-spacing:.2px;
+  white-space:nowrap;
+}
+
+tbody td{
+  padding: 10px 10px;
+  border-bottom: 1px solid rgba(13,20,33,.06);
+  font-size: 12.5px;
+  white-space:nowrap;
+}
+
+tbody tr:hover{background: rgba(56,97,251,.045)}
+
+.num{font-family: var(--mono); font-variant-numeric: tabular-nums; text-align:right}
+.right{text-align:right}
+.center{text-align:center}
+
+.namecell{display:flex; align-items:center; gap: 10px; min-width: 210px}
+.coin{
+  width: 26px;
+  height: 26px;
+  border-radius: 999px;
+  border: 1px solid rgba(13,20,33,.10);
+  background: radial-gradient(circle at 35% 25%, rgba(255,255,255,.7), transparent 55%),
+              linear-gradient(135deg, rgba(13,20,33,.08), rgba(56,97,251,.20));
+}
+.coin.alt{background: radial-gradient(circle at 35% 25%, rgba(255,255,255,.7), transparent 55%), linear-gradient(135deg, rgba(13,20,33,.08), rgba(22,199,132,.18))}
+.coin.stable{background: radial-gradient(circle at 35% 25%, rgba(255,255,255,.7), transparent 55%), linear-gradient(135deg, rgba(13,20,33,.06), rgba(128,138,157,.18))}
+.coin span{display:none}
+.names{
+  display:flex;
+  flex-direction:column;
+  line-height:1.1;
+}
+.names strong{font-size: 12.5px; font-weight: 850}
+.names em{font-style:normal; color: var(--muted); font-size: 11px; margin-top: 2px}
+
+.chg{font-family: var(--mono); font-variant-numeric: tabular-nums; text-align:right; font-weight: 750}
+.chg.positive{color: var(--green)}
+.chg.negative{color: var(--red)}
+.spark{
+  width: 110px;
+  height: 26px;
+  display:inline-block;
+}
+
+.index-row{
+  background: linear-gradient(90deg, rgba(56,97,251,.10), rgba(56,97,251,.03));
+}
+.index-row td{border-bottom: 1px solid rgba(56,97,251,.18)}
+.index-label{
+  display:flex;
+  flex-direction:column;
+  gap: 2px;
+}
+.index-label strong{font-size: 12.5px}
+.index-label span{font-size: 11px; color: rgba(13,20,33,.62)}
+
+.footerbar{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: 12px;
+  padding: 12px 14px;
+  border-top: 1px solid rgba(13,20,33,.08);
+}
+
+.pagination{display:flex; align-items:center; gap: 6px; flex-wrap:wrap}
+.page{
+  min-width: 34px;
+  height: 32px;
+  border-radius: 10px;
+  border: 1px solid rgba(13,20,33,.10);
+  background: rgba(255,255,255,.78);
+  font-size: 12px;
+  font-weight: 750;
+  cursor:pointer;
+  padding: 0 10px;
+}
+.page:hover{background: rgba(255,255,255,.98)}
+.page[aria-current="page"]{background: rgba(56,97,251,.12); border-color: rgba(56,97,251,.35)}
+.page:focus-visible{outline:none; box-shadow: var(--ring)}
+
+.summary{
+  padding: 14px 14px;
+}
+.summary p{margin:0; color: rgba(13,20,33,.78); font-size: 13px; line-height:1.55}
+.summary .more{display:none; margin-top: 10px; color: rgba(13,20,33,.70)}
+.summary .more.open{display:block}
+.linkbtn{
+  border: 0;
+  background: transparent;
+  color: var(--blue);
+  font-weight: 850;
+  cursor:pointer;
+  padding: 8px 0 0;
+}
+.linkbtn:focus-visible{outline:none; box-shadow: var(--ring); border-radius: 10px}
+
+.infogrid{
+  display:grid;
+  grid-template-columns: 1.4fr 1fr;
+  gap: 14px;
+}
+.prose{padding: 14px 14px}
+.prose h2{margin:0 0 8px; font-size: 14px; font-weight: 950}
+.prose p{margin:0; color: rgba(13,20,33,.76); font-size: 13px; line-height:1.55}
+.prose .stack{display:flex; flex-direction:column; gap: 12px}
+
+.footer{
+  padding: 18px 14px;
+  display:grid;
+  grid-template-columns: 1.4fr 1fr 1fr 1fr;
+  gap: 12px;
+}
+.footer h3{margin:0 0 8px; font-size: 12px; font-weight: 950; letter-spacing:.2px}
+.footer a{display:block; padding: 6px 0; font-size: 12px; color: rgba(13,20,33,.70)}
+.footer a:hover{color: var(--text)}
+.copyright{padding: 0 14px 18px; color: rgba(13,20,33,.55); font-size: 12px}
+
+@media (max-width: 1080px){
+  .statsbar{grid-template-columns: 1fr 1fr}
+  .infogrid{grid-template-columns: 1fr}
+  .brand{min-width:auto}
+}
+
+@media (max-width: 720px){
+  .navlinks{display:none}
+  .filters-grid{grid-template-columns: 1fr 1fr}
+  .statsbar{grid-template-columns: 1fr}
+  .container{padding: 14px 12px 30px}
+}
+
*** End Patch
PATCH

